sys_script.script:
(function executeRule(current, previous) {
	gs.info('[CampusOps] Reliability rule triggered for rental: ' + current.getUniqueValue());
    var studentId = current.getValue('u_student');

    if (!studentId) {
        current.setValue('u_reliability_score', 100);
        current.setValue('u_return_risk', 'low');
        return;
    }

    var score = 100;
    var rental = new GlideRecord('u_student_rental');
    rental.addQuery('u_student', studentId);
    rental.addQuery('sys_id', '!=', current.getUniqueValue());
    rental.query();

    while (rental.next()) {
        var status = (rental.getValue('u_status') || '').toLowerCase();

        if (status === 'returned') {
            var due = rental.getValue('u_due_date');
            var returned = rental.getValue('u_return_date');

            if (due && returned) {
                var dueDate = new GlideDateTime(due);
                var returnDate = new GlideDateTime(returned);

                if (returnDate.getNumericValue() <= dueDate.getNumericValue()) {
                    score += 20;
                } else {
                    score -= 15;
                }
            }
        } else if (status === 'active') {
            var dueValue = rental.getValue('u_due_date');

            if (dueValue &&
                new GlideDateTime(dueValue).getNumericValue() <
                new GlideDateTime().getNumericValue()) {
                score -= 25;
            }
        }
    }

    var currentStatus = (current.getValue('u_status') || '').toLowerCase();

    if (currentStatus === 'returned') {
        var currentDue = current.getValue('u_due_date');
        var currentReturn = current.getValue('u_return_date');

        if (currentDue && currentReturn) {
            if (new GlideDateTime(currentReturn).getNumericValue() <=
                new GlideDateTime(currentDue).getNumericValue()) {
                score += 20;
            } else {
                score -= 15;
            }
        }
    } else if (currentStatus === 'active') {
        var currentDueDate = current.getValue('u_due_date');

        if (currentDueDate &&
            new GlideDateTime(currentDueDate).getNumericValue() <
            new GlideDateTime().getNumericValue()) {
            score -= 25;
        }
    }

    score = Math.max(0, Math.min(100, score));

    var risk = 'low';

    if (score < 40) {
        risk = 'high';
    } else if (score < 70) {
        risk = 'medium';
    }

    current.setValue('u_reliability_score', score);
    current.setValue('u_return_risk', risk);

})(current, previous);
